/** Must match server `normalizeQuoteFormDraftUserEmail` (draft list is scoped to this user only). */
function normalizeDraftUserEmailForApi(raw) {
    return String(raw || '')
        .trim()
        .toLowerCase()
        .replace(/@almcg\.com/g, '@almoayyedcg.com');
}

/** Calendar YYYY-MM-DD for <input type="date" /> from EnquiryQuotes row (avoids TZ off-by-one on ISO datetimes). */
function quoteRowDateToInputYmd(quote) {
    if (!quote) return new Date().toISOString().split('T')[0];
    const ymd = quote.QuoteDateYmd ?? quote.quoteDateYmd;
    if (ymd && /^\d{4}-\d{2}-\d{2}$/.test(String(ymd).trim())) return String(ymd).trim();
    const raw = quote.QuoteDate ?? quote.quoteDate;
    if (raw == null || raw === '') return new Date().toISOString().split('T')[0];
    if (typeof raw === 'string') {
        const m = raw.trim().match(/^(\d{4}-\d{2}-\d{2})/);
        if (m) return m[1];
    }
    if (raw instanceof Date && !Number.isNaN(raw.getTime())) {
        const y = raw.getFullYear();
        const mo = String(raw.getMonth() + 1).padStart(2, '0');
        const da = String(raw.getDate()).padStart(2, '0');
        return `${y}-${mo}-${da}`;
    }
    return new Date().toISOString().split('T')[0];
}

/**
 * Local draft preview (Browse Previous Quotes **off**): Quote Ref shows full "Draft" when empty,
 * otherwise replaces the trailing revision segment (-R0, -R1, …) with `-Draft`.
 */
function quoteNumberToDraftDisplay(quoteNumber) {
    const s = String(quoteNumber || '').trim();
    if (!s) return 'Draft';
    return s.replace(/-R\d+$/i, '-Draft');
}

/** A4 To block: when the address contains Bahrain, keep "Kingdom of Bahrain" on its own line (case-insensitive). */
function formatQuotePreviewToAddressText(raw) {
    let s = String(raw || '').replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n');
    const re = /Kingdom of Bahrain/i;
    const m = s.match(re);
    if (!m || m.index === undefined) return s;
    const i = m.index;
    const matched = m[0];
    const lineStart = i === 0 ? 0 : s.lastIndexOf('\n', i - 1) + 1;
    const lineThrough = s.slice(lineStart, i + matched.length);
    if (lineThrough.trim() === matched) return s;
    const before = s.slice(0, i);
    const after = s.slice(i + matched.length);
    return `${before.trimEnd()}\n${matched}${after}`;
}

/** Resolve customer reference from enquiry payload shape variants (EnquiryMaster.CustomerRefNo). */
function resolveEnquiryCustomerRef(enquiry) {
    if (!enquiry || typeof enquiry !== 'object') return '';
    const candidates = [
        enquiry.CustomerRefNo,
        enquiry.customerRefNo,
        enquiry.CustomerReference,
        enquiry.customerReference,
        enquiry.YourRef,
        enquiry.yourRef,
    ];
    for (const v of candidates) {
        const s = String(v ?? '').trim();
        if (s) return s;
    }
    return '';
}

const QUOTE_DIVISION_SCOPE_NOTICE = 'Selected Division is not a part of this enquiry';

function quoteEnquiryDataHasDivisionJobs(data) {
    if (!data || typeof data !== 'object') return false;
    if (Array.isArray(data.divisions) && data.divisions.length > 0) return true;
    if (Array.isArray(data.divisionsHierarchy) && data.divisionsHierarchy.length > 0) return true;
    return false;
}

/** Resolve all enquiry types selected for a request from API payload variants. */
function resolveSelectedEnquiryTypes(payload) {
    if (!payload || typeof payload !== 'object') return [];
    const candidates = [
        payload?.enquiry?.SelectedEnquiryTypes,
        payload?.enquiry?.EnquiryTypes,
        payload?.enquiryTypes,
    ];
    for (const list of candidates) {
        if (Array.isArray(list) && list.length > 0) {
            return [...new Set(list.map((v) => String(v || '').trim()).filter(Boolean))];
        }
    }
    const fromCsv = String(payload?.enquiry?.EnquiryType || '').split(',').map((s) => s.trim()).filter(Boolean);
    return fromCsv.length > 0 ? [...new Set(fromCsv)] : [];
}

/** Previous Quotes list: quote date beside ref (EnquiryQuotes row). */
function formatQuoteRowListQuoteDate(q) {
    if (!q || typeof q !== 'object') return '';
    const ymd = q.QuoteDateYmd ?? q.quoteDateYmd;
    if (ymd && /^\d{4}-\d{2}-\d{2}$/.test(String(ymd).trim())) {
        try {
            return format(parseISO(String(ymd).trim()), 'dd-MMM-yyyy');
        } catch {
            /* fall through */
        }
    }
    const raw = q.QuoteDate ?? q.quoteDate;
    if (raw == null || raw === '') return '';
    try {
        const d = raw instanceof Date ? raw : new Date(raw);
        return !Number.isNaN(d.getTime()) ? format(d, 'dd-MMM-yyyy') : '';
    } catch {
        return '';
    }
}

/** Previous Quotes list: updated timestamp beside price. */
function formatQuoteRowListUpdatedAt(q) {
    if (!q || typeof q !== 'object') return '';
    const raw = q.UpdatedAt ?? q.updatedAt ?? q.CreatedAt ?? q.createdAt;
    if (raw == null || raw === '') return '';
    try {
        const d = raw instanceof Date ? raw : new Date(raw);
        return !Number.isNaN(d.getTime()) ? format(d, 'dd-MMM-yy hh:mm a') : '';
    } catch {
        return '';
    }
}

/** Previous Quotes list: reason for revision on EnquiryQuotes row. */
function quoteRowReasonForRevision(row) {
    if (!row || typeof row !== 'object') return '';
    return String(row.ReasonForRevision ?? row.reasonForRevision ?? row.reasonforrevision ?? '').trim();
}

/** Expandable reason block inside each Previous Quotes revision card. */
function QuoteRevisionReasonExpandable({ row }) {
    const [open, setOpen] = React.useState(false);
    const reason = quoteRowReasonForRevision(row);
    const revNo = Number(row?.RevisionNo ?? row?.revisionNo ?? 0);
    if (revNo <= 0 && !reason) return null;

    return (
        <div style={{ marginTop: '6px' }} onClick={(e) => e.stopPropagation()}>
            <button
                type="button"
                onClick={() => setOpen((v) => !v)}
                style={{
                    display: 'inline-flex',
                    alignItems: 'center',
                    gap: '4px',
                    padding: 0,
                    border: 'none',
                    background: 'transparent',
                    cursor: 'pointer',
                    fontSize: '10px',
                    fontWeight: 700,
                    color: '#b45309',
                }}
            >
                Reason for Revision
                {open ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
            </button>
            {open ? (
                <div
                    style={{
                        marginTop: '4px',
                        padding: '6px 8px',
                        background: '#fffbeb',
                        border: '1px solid #fde68a',
                        borderRadius: '4px',
                        fontSize: '10px',
                        color: '#78350f',
                        lineHeight: 1.4,
                        whiteSpace: 'pre-wrap',
                        wordBreak: 'break-word',
                    }}
                >
                    {reason || (
                        <span style={{ fontStyle: 'italic', color: '#94a3b8' }}>Not recorded</span>
                    )}
                </div>
            ) : null}
        </div>
    );
}

function normPreparedByName(s) {
    return (s || '').toLowerCase().replace(/\s+/g, ' ').trim();
}

function findUserByPreparedByName(name, usersList) {
    const n = normPreparedByName(name);
    if (!n || !Array.isArray(usersList)) return null;
    return usersList.find((x) => normPreparedByName(x.FullName) === n) || null;
}

function findUserByPreparedByEmail(email, usersList) {
    const e = String(email || '').toLowerCase().trim();
    if (!e || !Array.isArray(usersList)) return null;
    return (
        usersList.find((x) => String(x.EmailId || x.email || '').toLowerCase().trim() === e) || null
    );
}

/** True when a saved row email still belongs to the currently selected Prepared By name. */
function preparedByRowEmailMatchesName(rowEmail, preparedByName, usersList) {
    if (!rowEmail || !preparedByName) return false;
    const byEmail = findUserByPreparedByEmail(rowEmail, usersList);
    return !!byEmail && normPreparedByName(byEmail.FullName) === normPreparedByName(preparedByName);
}

function resolvePreparedByEmailFromName(name, usersList, currentUser) {
    const fromUser = findUserByPreparedByName(name, usersList);
    const email = String(fromUser?.EmailId || fromUser?.email || '').trim();
    if (email) return email;
    const selfName = (currentUser?.FullName || currentUser?.name || '').trim();
    if (normPreparedByName(selfName) === normPreparedByName(name)) {
        return String(currentUser?.EmailId || currentUser?.email || currentUser?.MailId || '').trim();
    }
    return '';
}

/**
 * A4 header block for **subjob** quote tabs: every value comes from the EnquiryQuotes row (not left-panel state).
 */
function buildSubjobQuoteHeaderDisplayFromRow(q, usersList, preparedByOptions) {
    if (!q || typeof q !== 'object') return null;
    const norm = (s) => (s || '').toLowerCase().replace(/\s+/g, ' ').trim();
    const email = String(q.PreparedByEmail ?? q.preparedbyemail ?? '').toLowerCase().trim();
    let contact = '';
    if (email && Array.isArray(usersList)) {
        const u = usersList.find((x) => String(x.EmailId || x.email || '').toLowerCase().trim() === email);
        if (u?.MobileNumber != null) {
            contact = String(u.MobileNumber).trim().replace(/^tel\s*:?\s*/i, '').trim();
        }
    }
    const prepName = String(q.PreparedBy ?? q.preparedby ?? '').trim();
    if (!contact && prepName && Array.isArray(usersList)) {
        const n = norm(prepName);
        const fromU = usersList.find((x) => norm(x.FullName) === n);
        if (fromU?.MobileNumber != null) {
            contact = String(fromU.MobileNumber).trim().replace(/^tel\s*:?\s*/i, '').trim();
        }
    }
    if (!contact && prepName && Array.isArray(preparedByOptions)) {
        const n = norm(prepName);
        const po = preparedByOptions.find(
            (o) => norm(String(o.value || '')) === n || norm(String(o.label || '')) === n
        );
        const pMob = (po?.mobileNumber != null ? String(po.mobileNumber) : '').trim();
        if (pMob) contact = pMob.replace(/^tel\s*:?\s*/i, '').trim();
    }
    const ymd = quoteRowDateToInputYmd(q);
    const validityDayCount = parseInt(q.ValidityDays ?? q.validitydays ?? 30, 10);
    let validityDisplay = '';
    try {
        const base = /^\d{4}-\d{2}-\d{2}$/.test(String(ymd).trim())
            ? parseISO(String(ymd).trim())
            : new Date(ymd);
        if (!Number.isNaN(base.getTime())) {
            validityDisplay = format(addDays(base, validityDayCount), 'dd-MMM-yyyy');
        }
    } catch {
        validityDisplay = '';
    }
    const typeParts = String(q.QuoteType ?? q.quotetype ?? '')
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);
    const quoteTypeLine = typeParts.length ? typeParts.join(', ') : '—';
    return {
        toName: String(q.ToName ?? q.toname ?? '').trim(),
        toAddress: String(q.ToAddress ?? q.toaddress ?? '').trim(),
        toPhone: String(q.ToPhone ?? q.tophone ?? '').trim(),
        toFax: String(q.ToFax ?? q.tofax ?? '').trim(),
        toEmail: String(q.ToEmail ?? q.toemail ?? '').trim(),
        toAttention: String(q.ToAttention ?? q.toattention ?? '').trim(),
        preparedBy: prepName,
        preparedByContact: contact,
        preparedByEmail: String(q.PreparedByEmail ?? q.preparedbyemail ?? '').trim(),
        quoteNumber: String(q.QuoteNumber ?? q.quoteNumber ?? '').trim(),
        quoteDateYmd: ymd,
        validityDisplay,
        validityDayCount,
        quoteTypeLine,
        customerReference: String(
            q.CustomerReference ?? q.customerreference ?? q.YourRef ?? q.yourref ?? ''
        ).trim(),
        subject: String(q.Subject ?? q.subject ?? '').trim(),
        signatory: String(q.Signatory ?? q.signatory ?? '').trim(),
        signatoryDesignation: String(q.SignatoryDesignation ?? q.signatorydesignation ?? '').trim(),
        coSignatory: String(q.CoSignatory ?? q.coSignatory ?? '').trim(),
        coSignatoryDesignation: String(q.CoSignatoryDesignation ?? q.coSignatoryDesignation ?? '').trim(),
    };
}

function formatQuoteYmdForDisplay(ymd) {
    if (!ymd) return '';
    const s = String(ymd).trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
        try {
            return format(parseISO(s), 'dd-MMM-yyyy');
        } catch {
            return s;
        }
    }
    try {
        return format(new Date(s), 'dd-MMM-yyyy');
    } catch {
        return s;
    }
}

/** Quote Details validity value: end date plus day span from quote date, e.g. "12-Jun-2026 (30 days)". */
function formatQuoteValidityLineForDetails(validityDisplay, dayCount) {
    const disp = String(validityDisplay || '').trim();
    if (!disp) return '';
    const n = parseInt(String(dayCount), 10);
    if (Number.isNaN(n) || n < 0) return disp;
    return `${disp} (${n} day${n === 1 ? '' : 's'})`;
}

/** Pick enquiry row when user presses Enter in the left-panel search box. */
function pickEnquiryForSearchEnter(term, suggestions) {
    const t = String(term || '').trim();
    if (!t) return null;
    const tl = t.toLowerCase();
    const list = Array.isArray(suggestions) ? suggestions : [];
    if (list.length) {
        const exactNo = list.find((e) => String(e.RequestNo || '').trim().toLowerCase() === tl);
        if (exactNo) return exactNo;
        const exactProj = list.find((e) => String(e.ProjectName || '').trim().toLowerCase() === tl);
        if (exactProj) return exactProj;
        const exactCust = list.find((e) => String(e.CustomerName || '').trim().toLowerCase() === tl);
        if (exactCust) return exactCust;
        if (list.length === 1) return list[0];
    }
    return { RequestNo: t, ProjectName: '' };
}

/** Stable reference when there are zero quote tabs (avoids new [] every memo pass). */
const EMPTY_CALCULATED_TABS = [];
/** Stable empty list for department attention fetch clears. */
const EMPTY_DEPT_ATTENTION_NAMES = [];

// Default clause templates (HTML: one block per numbered point so editors stack lines by default)
