        if (defHit?.imageDataUrl) return defHit;
        if (userSignatureLibrary[0]?.imageDataUrl) return userSignatureLibrary[0];
        const fallbackUrl = resolveDefaultSignatureImage(signatureLibraryEmail);
        return fallbackUrl ? { imageDataUrl: fallbackUrl } : null;
