        const prepOpts = divisionPickerOptions.preparedBy || [];
        const sigOpts =
            (divisionPickerOptions.signatory || []).length > 0
                ? divisionPickerOptions.signatory
                : prepOpts;
        const prep = (preparedBy || '').trim();
        if (prep && prepOpts.length > 0) {
            const prepValid = prepOpts.some((o) => String(o.value || '').trim() === prep);
            if (!prepValid) setPreparedBy('');
        }
        const sig = (signatory || '').trim();
        if (sig && sigOpts.length > 0) {
            const sigValid = sigOpts.some((o) => String(o.value || '').trim() === sig);
            if (!sigValid) {
                setSignatory('');
                setSignatoryDesignation('');
                setCoSignatory('');
                setCoSignatoryDesignation('');
            }
        }
