        setExistingQuotes([]);
        setQuoteScopedForPanel([]);
        setScopedQuotesFetchSettledKey(null);
        setPendingFiles([]); // Clear queue
        leadChoiceFingerprintRef.current = '';
        autoSelectCustomerAfterLeadChangeRef.current = false;
        setLeadSwitchShellHold(false);
