        if (pending?.contentKey != null && pending.val != null) {
            if (pending.isCustom) {
                mergedCustomClauses = (customClauses || []).map((c) =>
                    c.id === pending.contentKey ? { ...c, content: pending.val } : c
                );
            } else {
                mergedClauseContent = { ...mergedClauseContent, [pending.contentKey]: pending.val };
            }
        }

        const live = editingClauseLiveHtmlRef.current;
        if (live?.key && live.html != null) {
            if (String(live.key).startsWith('custom_')) {
                mergedCustomClauses = (customClauses || []).map((c) =>
                    c.id === live.key ? { ...c, content: live.html } : c
                );
            } else {
                mergedClauseContent = { ...mergedClauseContent, [live.key]: live.html };
            }
        }

        if (mergedClauseContent.pricingTerms) {
            mergedClauseContent.pricingTerms = ensurePricingTableColgroupInHtml(
                mergedClauseContent.pricingTerms
            );
            if (clauseHtmlHasEmsAutoPricingTable(mergedClauseContent.pricingTerms)) {
                pricingTermsUserTouchedRef.current = true;
            }
        }

        return { mergedClauseContent, mergedCustomClauses };
