    const fetchApprovalStepsFromServer = useCallback(async (overrideQuoteId) => {
        const targetQuoteId = (() => {
            if (overrideQuoteId != null && Number.isFinite(Number(overrideQuoteId))) {
                return Number(overrideQuoteId);
            }
            if (embeddedApprovalReview) {
                const id =
                    quoteId ||
                    (String(openContext?.quoteId || '').trim()
                        ? Number(openContext.quoteId)
                        : null);
                return Number.isFinite(id) ? id : null;
            }
            if (!browsePreviousQuotesRevisions || !quoteId) return null;
            return Number(quoteId);
        })();

        if (!targetQuoteId || !Number.isFinite(targetQuoteId)) return;

        const seq = ++approvalStepsFetchSeqRef.current;
        setApprovalWorkflowStepsLoading(true);

        try {
            const params = new URLSearchParams();
            params.set('quoteId', String(targetQuoteId));
            const res = await fetch(`${API_BASE}/api/quotes/approval-steps?${params.toString()}`, {
                cache: 'no-store',
            });
            if (seq !== approvalStepsFetchSeqRef.current) return;
            if (!res.ok) return;
            const data = await res.json();
            if (seq !== approvalStepsFetchSeqRef.current) return;
            approvalStepsSkipSaveRef.current = true;
            setApprovalWorkflowSteps(normalizeApprovalStepsFromApi(data.steps));
            setApprovalRequestSent(Boolean(data.approvalRequestSent));
            setApprovalWorkflowCreatorCompanyName(String(data.createdByCompanyName || '').trim());
            setApprovalWorkflowCreatorDivisionName(String(data.createdByDivisionName || '').trim());
            const apiBranding = data.creatorCompanyBranding;
            setApprovalWorkflowCreatorBranding(
                apiBranding && apiBranding.name
                    ? {
                          name: String(apiBranding.name || '').trim(),
                          logo: apiBranding.logo ? String(apiBranding.logo).trim() : null,
                          address: String(apiBranding.address || '').trim(),
                          phone: String(apiBranding.phone || '').trim(),
                          fax: String(apiBranding.fax || '').trim(),
                          email: String(apiBranding.email || '').trim(),
                      }
                    : null
            );
            window.setTimeout(() => {
                approvalStepsSkipSaveRef.current = false;
            }, 800);
        } catch (e) {
            if (seq === approvalStepsFetchSeqRef.current) {
                console.warn('[QuoteForm] fetch approval steps', e);
            }
        } finally {
            if (seq === approvalStepsFetchSeqRef.current) {
                setApprovalWorkflowStepsLoading(false);
            }
        }
    }, [embeddedApprovalReview, browsePreviousQuotesRevisions, quoteId, openContext?.quoteId]);

